 18| export class IceMonitorService {
 19|   private readonly cancelling = new Set<string>();
 20| 
 21|   constructor(
 22|     private readonly sessions: SessionRepository,
 23|     private readonly bookings: BookingRepository,
 24|     private readonly readings: TemperatureRepository,
 25|     private readonly puckPay: PuckPayGateway,
 26|     private readonly texts: TextGateway,
 27|     private readonly now: () => number = Date.now,
 28|   ) {}
