 30|   /** Records a sensor reading; holds the next session once the ice has been warm for long enough. */
 31|   async recordReading(input: NewReading): Promise<{ heldSessionId?: string }> {
 32|     if (typeof input.celsius !== "number" || !Number.isFinite(input.celsius))
 33|       throw new DomainError(400, "temperature must be a number");
 34|     if (input.at !== undefined && !Number.isFinite(input.at))
 35|       throw new DomainError(400, "timestamp is invalid");
 36|     this.readings.add({ at: input.at ?? this.now(), celsius: input.celsius });
 37| 
 38|     if (!this.warmLongEnough()) return {};
 39|     const next = this.nextSession();
 40|     if (!next || next.status !== "open") return {};
 41| 
 42|     // Status changes synchronously, so concurrent readings cannot hold the same session twice.
 43|     next.status = "held";
 44|     this.sessions.save(next);
 45|     await this.notifyHolders(next);
 46|     return { heldSessionId: next.id };
 47|   }
 48| 
 49|   /** Manager cancels a held session: every paid ticket is refunded through PuckPay. */
 50|   async cancel(sessionId: string): Promise<Session> {
 51|     const session = this.heldSession(sessionId);
 52|     if (this.cancelling.has(sessionId)) throw new DomainError(409, "session is already being cancelled");
 53|     this.cancelling.add(sessionId);
 54|     try {
 55|       const failures: string[] = [];
 56|       for (const b of this.bookings.findBySession(sessionId)) {
 57|         if (b.status === "pending") {
 58|           b.status = "cancelled";
 59|           this.bookings.save(b);
 60|         } else if (b.status === "paid") {
 61|           if (b.amountCents > 0) {
 62|             try {
 63|               await this.puckPay.refund(b.id, b.amountCents);
 64|             } catch (err) {
 65|               failures.push(`${b.id}: ${(err as Error).message}`);
 66|               continue;
 67|             }
 68|             b.status = "refunded";
 69|           } else {
 70|             b.status = "cancelled"; // free member entry, nothing to refund
 71|           }
 72|           this.bookings.save(b);
 73|         }
 74|       }
 75|       if (failures.length > 0) {
 76|         // Session stays held so the manager can retry; refunded bookings are skipped next time.
 77|         throw new DomainError(502, `could not refund all tickets: ${failures.join("; ")}`);
 78|       }
 79|       session.status = "cancelled";
 80|       this.sessions.save(session);
 81|       return session;
 82|     } finally {
 83|       this.cancelling.delete(sessionId);
 84|     }
 85|   }
 86| 
 87|   /** Manager lifts the hold; ticket sales resume. */
 88|   release(sessionId: string): Session {
 89|     const session = this.heldSession(sessionId);
 90|     if (this.cancelling.has(sessionId)) throw new DomainError(409, "session is being cancelled");
 91|     session.status = "open";
 92|     this.sessions.save(session);
 93|     // Require a fresh warm period before holding again.
 94|     this.readings.clear();
 95|     return session;
 96|   }
 97| 
 98|   private heldSession(id: string): Session {
 99|     const session = this.sessions.findById(id);
100|     if (!session) throw new DomainError(404, "session not found");
101|     if (session.status !== "held") throw new DomainError(409, "session is not on hold");
102|     return session;
103|   }
104| 
105|   /** True when the readings end in a run of warm readings spanning at least ten minutes. */
106|   private warmLongEnough(): boolean {
107|     const all = this.readings.all();
108|     let runStart: number | undefined;
109|     for (let i = all.length - 1; i >= 0; i--) {
110|       if (all[i]!.celsius <= WARM_THRESHOLD_C) break;
111|       runStart = all[i]!.at;
112|     }
113|     if (runStart === undefined) return false;
114|     return all[all.length - 1]!.at - runStart >= WARM_DURATION_MS;
115|   }
116| 
117|   /** The earliest session that has not started yet. */
118|   private nextSession(): Session | undefined {
119|     const now = this.now();
120|     return this.sessions
121|       .findAll()
122|       .map((s) => ({ s, startsAt: new Date(`${s.date}T${s.start}:00`).getTime() }))
123|       .filter((x) => x.startsAt > now && x.s.status !== "cancelled")
124|       .sort((a, b) => a.startsAt - b.startsAt)[0]?.s;
125|   }
126| 
127|   private async notifyHolders(session: Session): Promise<void> {
128|     const message =
129|       `Your ice rink session on ${session.date} ${session.start}-${session.end} is on hold ` +
130|       `because the ice is too warm. We will let you know whether it goes ahead.`;
131|     const phones = new Set<string>();
132|     for (const b of this.bookings.findBySession(session.id)) {
133|       if ((b.status === "paid" || b.status === "pending") && b.phone) phones.add(b.phone);
134|     }
135|     await Promise.all(
136|       [...phones].map((phone) =>
137|         this.texts.send(phone, message).catch((err) => {
138|           console.error(`could not text ${phone}: ${(err as Error).message}`);
139|         }),
140|       ),
141|     );
142|   }
143| }
